"""Summarize a CSV with category,amount,status — only paid rows."""

import csv
import json
import sys
from collections import defaultdict
from decimal import Decimal, ROUND_HALF_UP

TWO_PLACES = Decimal("0.01")


def normalize_category(raw: str) -> str:
    """Collapse whitespace, casefold; blank → 'uncategorized'."""
    collapsed = " ".join(raw.split())
    folded = collapsed.casefold()
    return folded if folded else "uncategorized"


def process(input_path: str) -> dict:
    totals: dict[str, Decimal] = defaultdict(Decimal)
    grand_total = Decimal("0")

    with open(input_path, newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        for row in reader:
            status = (row.get("status") or "").strip().casefold()
            if status != "paid":
                continue

            cat = normalize_category(row.get("category") or "")
            amt = Decimal(row["amount"].strip())
            rounded = amt.quantize(TWO_PLACES, rounding=ROUND_HALF_UP)

            totals[cat] += rounded
            grand_total += rounded

    categories = [
        {"category": name, "total": str(t.quantize(TWO_PLACES, rounding=ROUND_HALF_UP))}
        for name, t in sorted(totals.items())
    ]
    return {
        "categories": categories,
        "total": str(grand_total.quantize(TWO_PLACES, rounding=ROUND_HALF_UP)),
    }


def main() -> None:
    if len(sys.argv) < 2:
        sys.exit("Usage: solution.py <input.csv>")
    result = process(sys.argv[1])
    print(json.dumps(result))


